describe('Dropdown Escape Key Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="dropdown-trigger"]').as('dropdownTrigger');
    cy.get('[data-testid="dropdown-menu"]').as('dropdownMenu');
  });

  it('should close dropdown when Escape key is pressed', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');
    cy.get('@dropdownMenu').should('have.attr', 'aria-hidden', 'false');

    cy.get('body').type('{esc}');

    cy.get('@dropdownMenu').should('not.be.visible');
    cy.get('@dropdownMenu').should('have.attr', 'aria-hidden', 'true');
    cy.get('@dropdownTrigger').should('have.focus');
  });

  it('should close nested dropdown when Escape is pressed from submenu', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('[data-testid="dropdown-submenu-trigger"]').click();
    cy.get('[data-testid="dropdown-submenu"]').should('be.visible');

    cy.get('body').type('{esc}');

    cy.get('[data-testid="dropdown-submenu"]').should('not.be.visible');
    cy.get('[data-testid="dropdown-submenu-trigger"]').should('have.focus');
  });

  it('should not close dropdown when Escape is pressed on non-focused element', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('[data-testid="external-element"]').type('{esc}');

    cy.get('@dropdownMenu').should('be.visible');
  });

  it('should handle multiple consecutive Escape presses', () => {
    cy.get('@dropdownTrigger').click();
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('body').type('{esc}{esc}');

    cy.get('@dropdownMenu').should('not.be.visible');
    cy.get('@dropdownTrigger').should('have.focus');
  });

  it('should close dropdown and maintain focus management on Escape', () => {
    cy.get('@dropdownTrigger').focus();
    cy.get('@dropdownTrigger').type('{enter}');
    cy.get('@dropdownMenu').should('be.visible');

    cy.get('[data-testid="dropdown-item"]').first().focus();
    cy.get('body').type('{esc}');

    cy.get('@dropdownMenu').should('not.be.visible');
    cy.get('@dropdownTrigger').should('have.focus');
  });

  it('should close dropdown with Escape when opened via keyboard navigation', () => {
    cy.get('@dropdownTrigger').focus();
    cy.get('@dropdownTrigger').type('{downarrow}');
    cy.get('@dropdownMenu').should('be.visible');
    cy.get('[data-testid="dropdown-item"]').first().should('have.focus');

    cy.get('body').type('{esc}');

    cy.get('@dropdownMenu').should('not.be.visible');
    cy.get('@dropdownTrigger').should('have.focus');
  });
});
